response.body:
{
  "status": true,
  "message": "Virtual bank account created successfully",
  "data": {
    "account_name": "{{jsonPath request.body '$.account_name'}}",
    "account_number": "0657789765",
    "bank_code": "{{val (jsonPath request.body '$.bank_code') default='070'}}",
    "bank_name": "Fidelity Bank",
    "account_reference": "{{jsonPath request.body '$.account_reference'}}",
    "unique_id": "KPY-VBA-{{jsonPath request.body '$.account_reference'}}",
    "account_status": "active",
    "created_at": "{{now format='yyyy-MM-dd\'T\'HH:mm:ss\'Z\''}}",
    "currency": "{{val (jsonPath request.body '$.currency') default='NGN'}}",
    "customer": {
      "name": "{{val (jsonPath request.body '$.customer.name') default='VBA Customer'}}",
      "email": "{{val (jsonPath request.body '$.customer.email') default='vba@kora.test'}}"
    }
  }
}

{
  "status": true,
  "message": "Virtual bank account transactions retrieved successfully",
  "data": {
    "total_amount_received": 15000.0,
    "account_number": "{{val request.query.account_number default='0657789765'}}",
    "currency": "NGN",
    "transactions": [
      {
        "reference": "KPY-VBA-TX-001",
        "status": "success",
        "amount": "15000.00",
        "fee": "150.00",
        "currency": "NGN",
        "description": "Inward Transfer to Virtual Account",
        "payer_bank_account": {
          "account_name": "ALICE WONDERLAND",
          "account_number": "0123456789",
          "bank_name": "Guaranty Trust Bank"
        }
      }
    ],
    "pagination": {
      "page": 1,
      "total": 1,
      "per_page": 20,
      "total_pages": 1
    }
  }
}

{
  "status": true,
  "message": "Virtual bank account retrieved successfully",
  "data": {
    "account_name": "{{state context=request.path.account_reference property='account_name' default='VBA Account'}}",
    "account_number": "{{state context=request.path.account_reference property='account_number' default='0657789765'}}",
    "bank_code": "{{state context=request.path.account_reference property='bank_code' default='070'}}",
    "bank_name": "{{state context=request.path.account_reference property='bank_name' default='Fidelity Bank'}}",
    "account_reference": "{{state context=request.path.account_reference property='account_reference' default=request.path.account_reference}}",
    "unique_id": "KPY-VBA-{{request.path.account_reference}}",
    "account_status": "{{state context=request.path.account_reference property='account_status' default='active'}}",
    "created_at": "{{state context=request.path.account_reference property='createdAt' default='2025-01-01T00:00:00Z'}}",
    "currency": "{{state context=request.path.account_reference property='currency' default='NGN'}}",
    "customer": {
      "name": "{{state context=request.path.account_reference property='customerName' default='VBA Customer'}}",
      "email": "{{state context=request.path.account_reference property='customerEmail' default='vba@kora.test'}}"
    }
  }
}

{
  "status": false,
  "message": "Virtual bank account with reference '{{request.path.account_reference}}' was not found.",
  "data": null
}

{
  "status": true,
  "message": "Sandbox virtual bank account credited successfully",
  "data": {
    "account_number": "{{jsonPath request.body '$.account_number'}}",
    "amount": "{{jsonPath request.body '$.amount'}}",
    "currency": "{{val (jsonPath request.body '$.currency') default='NGN'}}",
    "status": "success"
  }
}
